import java.util.*;

class Solution {
    private Map<Integer, Integer> inorderIndex;
    private int preorderIndex;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        inorderIndex = new HashMap<>();
        for (int i = 0; i < inorder.length; i++) {
            inorderIndex.put(inorder[i], i);
        }
        preorderIndex = 0;
        return build(preorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int inLeft, int inRight) {
        if (inLeft > inRight) return null;

        int rootVal = preorder[preorderIndex++];
        TreeNode root = new TreeNode(rootVal);
        int rootIndex = inorderIndex.get(rootVal);

        root.left = build(preorder, inLeft, rootIndex - 1);
        root.right = build(preorder, rootIndex + 1, inRight);
        return root;
    }
}

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        return build(preorder, 0, preorder.length - 1, inorder, 0, inorder.length - 1);
    }

    private TreeNode build(int[] preorder, int preStart, int preEnd,
                           int[] inorder, int inStart, int inEnd) {
        if (preStart > preEnd || inStart > inEnd) return null;

        int rootVal = preorder[preStart];
        TreeNode root = new TreeNode(rootVal);

        int rootIndex = inStart;
        while (inorder[rootIndex] != rootVal) {
            rootIndex++;
        }

        int leftSize = rootIndex - inStart;
        root.left = build(preorder, preStart + 1, preStart + leftSize,
                inorder, inStart, rootIndex - 1);
        root.right = build(preorder, preStart + leftSize + 1, preEnd,
                inorder, rootIndex + 1, inEnd);
        return root;
    }
}

import java.util.*;

class Solution {
    public TreeNode buildTree(int[] preorder, int[] inorder) {
        TreeNode root = new TreeNode(preorder[0]);
        Deque<TreeNode> stack = new ArrayDeque<>();
        stack.push(root);
        int inorderIndex = 0;

        for (int i = 1; i < preorder.length; i++) {
            int value = preorder[i];
            TreeNode parent = stack.peek();

            if (parent.val != inorder[inorderIndex]) {
                parent.left = new TreeNode(value);
                stack.push(parent.left);
            } else {
                while (!stack.isEmpty() && stack.peek().val == inorder[inorderIndex]) {
                    parent = stack.pop();
                    inorderIndex++;
                }
                parent.right = new TreeNode(value);
                stack.push(parent.right);
            }
        }

        return root;
    }
}

class Solution {
    private int preorderIndex;
    private int inorderIndex;

    public TreeNode buildTree(int[] preorder, int[] inorder) {
        preorderIndex = 0;
        inorderIndex = 0;
        return build(preorder, inorder, null);
    }

    private TreeNode build(int[] preorder, int[] inorder, Integer stop) {
        if (preorderIndex == preorder.length) return null;
        if (stop != null && inorder[inorderIndex] == stop) return null;

        int rootVal = preorder[preorderIndex++];
        TreeNode root = new TreeNode(rootVal);
        root.left = build(preorder, inorder, rootVal);
        inorderIndex++;
        root.right = build(preorder, inorder, stop);
        return root;
    }
}
